import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"告警：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","frontmatter":{"title":"告警：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","showdocs":{"topics":[{"id":"alerting","title":"告警与问题定位","link":"/topics/alerting/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"告警与问题定位机制与任务课程","summary":"把维护动作、症状调查和同一故障场景的验收放在一起。","status":"active","related":[{"title":"告警与问题定位：配置规则、分组与通知路由","link":"/systems/logging-monitoring/alerting/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"告警：基础对象与机制","link":"/systems/logging-monitoring/alerting/alert-lifecycle","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"告警与问题定位：配置规则、分组与通知路由","link":"/systems/logging-monitoring/alerting/plus/practice/application"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"告警与问题定位：配置规则、分组与通知路由","link":"/systems/logging-monitoring/alerting/plus/practice/application"},"next":false},"headers":[],"relativePath":"systems/logging-monitoring/alerting/operations.md","filePath":"systems/logging-monitoring/alerting/operations.md"}'),n={name:"systems/logging-monitoring/alerting/operations.md"};function l(o,e,s,p,c,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="告警-发布、排障与恢复练习" tabindex="-1">告警：发布、排障与恢复练习 <a class="header-anchor" href="#告警-发布、排障与恢复练习" aria-label="Permalink to &quot;告警：发布、排障与恢复练习&quot;">​</a></h1><h2 id="part-1" tabindex="-1">值班、静默、变更与消噪 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;值班、静默、变更与消噪 {#part-1}&quot;">​</a></h2><p>维护Prometheus 告警与通知前先保存规则标签、for、路由与接收端，恢复后以pending/firing、静默/抑制与投递结果验收。具体配置见<a href="/systems/logging-monitoring/alerting/plus/practice/application#files">配套示例</a>。</p><p>核对日期2026-10-17；适用范围：机制按核对时Prometheus 3.x官方文档的稳定共同子集说明；示例另固定Prometheus 2.55与Alertmanager 0.28教学配置族，归档族不是生产安装建议。新版新增或实验功能未默认启用，实际升级仍需独立兼容与安全评估。示例未执行；真实环境仍需验证产品配置、权限、连通与恢复结果。先读<a href="/systems/logging-monitoring/alerting/alert-lifecycle#part-1-ownership">起点</a>理解前置，再按章节完成推演。</p><h3 id="part-1-flap" tabindex="-1">抖动与恢复策略 <a class="header-anchor" href="#part-1-flap" aria-label="Permalink to &quot;抖动与恢复策略 {#part-1-flap}&quot;">​</a></h3><p>告警抖动通常来自阈值附近波动、缺样本或标签不稳定。先确认信号和用户影响，再选择合理for、窗口或进入/退出门槛；延长for会降低噪声也会增加发现延迟。repeat_interval只影响重复通知，不会修复规则抖动。不要动态把当前值写进label，那会每次产生新告警并重置pending；动态说明放annotation，仍需脱敏。</p><h3 id="part-1-maintenance" tabindex="-1">维护静默与审批 <a class="header-anchor" href="#part-1-maintenance" aria-label="Permalink to &quot;维护静默与审批 {#part-1-maintenance}&quot;">​</a></h3><p>告警维护静默必须限定service/环境、明确起止时间、责任人和变更单，结束后确认自动过期且观察信号恢复。长期全局silence掩盖新事故，删除全部告警状态也不是降噪。路由变更先在副本评估覆盖集合，再核对兜底接收端和恢复通知。集群多副本去重依赖身份与标签稳定，课堂单机配置不宣称HA通知无丢失。</p><h3 id="part-1-incident" tabindex="-1">事件响应与证据 <a class="header-anchor" href="#part-1-incident" aria-label="Permalink to &quot;事件响应与证据 {#part-1-incident}&quot;">​</a></h3><p>告警事件响应先确认用户影响与范围，再保全表达式、标签、时间窗、部署版本和日志关联ID。紧急缓解与根因修复分开记录，回退后验证业务指标、采集健康和通知恢复三项。不要把“收到恢复通知”当作数据库一致性或全部用户恢复的证明；必要时核对代表性业务路径。复盘将误报、漏报和行动耗时转为下一次规则改进。</p><h3 id="part-1-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-1-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-1-selfcheck}&quot;">​</a></h3><p>练习：修改repeat_interval能解决阈值上下跳动吗？</p><details><summary>参考解答</summary><p>不能。它只控制重复提醒，阈值/窗口/for和稳定label才影响规则抖动；延长for也会增加发现延迟。</p></details><h3 id="part-1-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-1-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-1-references}&quot;">​</a></h3><ul><li><p><a href="https://prometheus.io/docs/prometheus/latest/configuration/alerting_rules/" target="_blank" rel="noopener noreferrer">Prometheus 3.x当前规则文档核对</a></p></li><li><p><a href="https://grafana.com/docs/grafana/latest/administration/provisioning/" target="_blank" rel="noopener noreferrer">Grafana provisioning核对</a></p></li><li><p><a href="https://prometheus.io/docs/prometheus/2.55/configuration/alerting_rules/" target="_blank" rel="noopener noreferrer">告警规则2.55</a></p></li><li><p><a href="https://prometheus.io/docs/alerting/0.28/configuration/" target="_blank" rel="noopener noreferrer">路由配置0.28</a></p></li><li><p><a href="https://prometheus.io/docs/alerting/latest/overview/" target="_blank" rel="noopener noreferrer">告警职责</a></p></li></ul><p>继续阅读<a href="/systems/logging-monitoring/alerting/alert-lifecycle#part-2-pending">机制</a>、<a href="/systems/logging-monitoring/alerting/plus/practice/application#files">完整实践</a>、<a href="#part-1-flap">运维</a>、<a href="#part-2-silent">诊断</a>与<a href="#part-3-exercise">复习</a>。</p><h2 id="part-2" tabindex="-1">有告警无通知与告警风暴定位 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;有告警无通知与告警风暴定位 {#part-2}&quot;">​</a></h2><p>本节沿pending/firing、静默/抑制与投递结果定位失败层；先确认规则标签、for、路由与接收端，与<a href="/systems/logging-monitoring/alerting/plus/practice/application#files">配套示例</a>逐项对照，再选择最小修复。</p><h3 id="part-2-silent" tabindex="-1">Firing却无通知 <a class="header-anchor" href="#part-2-silent" aria-label="Permalink to &quot;Firing却无通知 {#part-2-silent}&quot;">​</a></h3><p>告警无通知排查先在规则层确认firing实例与完整标签，再查看到Alertmanager的连接、路由匹配、group_wait、silence/inhibition与接收端错误。保留域失败是课堂预期，不应通过关闭TLS验证绕过。标签拼写不一致可能落入discard；重复周期长不等于丢失。按同一告警指纹追踪三层证据，避免先重启所有监控组件破坏状态。</p><h3 id="part-2-missing" tabindex="-1">消失序列与误恢复 <a class="header-anchor" href="#part-2-missing" aria-label="Permalink to &quot;消失序列与误恢复 {#part-2-missing}&quot;">​</a></h3><p>告警误恢复可能是发现目标消失、表达式过滤排除或采集标签变化，不能只因为up==0不再firing就认定服务恢复。独立Missing规则检测窗口完整缺失，结合期望目标清单才可识别具体缺失实例。缺失窗口越大越慢但更能抗短暂断点，需由业务允许的检测时延决定。Grafana告警另有NoData/Error状态，不能把它们套到本例Prometheus状态机。</p><h3 id="part-2-storm" tabindex="-1">告警风暴的定位 <a class="header-anchor" href="#part-2-storm" aria-label="Permalink to &quot;告警风暴的定位 {#part-2-storm}&quot;">​</a></h3><p>告警风暴先看是否同一上游故障引发多服务次要异常，再检查group_by过细、动态label和错误抑制范围。练习：把request_id加入告警label会怎样？参考解答：实例身份不断改变，通知无法稳定分组去重，for可能反复重置；改放annotation或受控日志关联，并选择稳定service/instance身份。抑制应保留根因通知，不能一键丢弃所有warning当作问题解决。</p><h3 id="part-2-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-2-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-2-selfcheck}&quot;">​</a></h3><p>练习：Firing但没有消息应先删除Alertmanager数据吗？</p><details><summary>参考解答</summary><p>不应。先跟踪标签、发送连接、路由、静默/抑制与接收端错误，删除状态会破坏证据。</p></details><h3 id="part-2-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-2-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-2-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p><h2 id="part-3" tabindex="-1">规则触发但无人收到的复盘 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;规则触发但无人收到的复盘 {#part-3}&quot;">​</a></h2><p>以下演练将Prometheus 告警与通知的变更、失败证据和恢复验收串起来；先熟悉<a href="/systems/logging-monitoring/alerting/plus/practice/application#files">配套示例</a>中的规则标签、for、路由与接收端。演练未执行。</p><h3 id="part-3-incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#part-3-incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#part-3-incident-scenario}&quot;">​</a></h3><p>规则页面显示 firing，值班人员却没有收到通知。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h3 id="part-3-incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#part-3-incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#part-3-incident-evidence}&quot;">​</a></h3><ol><li>记录告警标签、开始时间和规则版本，区分 pending、firing 与已恢复状态。</li><li>按标签检查路由、分组、静默和抑制，确认实际选中的接收器与预期一致。</li><li>检查投递错误及接收端结果；规则触发、发送尝试和人员接收分别取证。</li></ol><h3 id="part-3-incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#part-3-incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#part-3-incident-recovery}&quot;">​</a></h3><p>修正具体路由或投递故障，必要时启用已准备的备用联络渠道；保留必要抑制，避免为验证通知而放大整套告警。</p><p>验收：通过受控测试验证触发、接收、确认与恢复全流程；空数据与依赖故障也有明确策略，通知中包含可执行的处理入口。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://prometheus.io/docs/practices/alerting/" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h3 id="part-3-exercise" tabindex="-1">三层状态练习 <a class="header-anchor" href="#part-3-exercise" aria-label="Permalink to &quot;三层状态练习 {#part-3-exercise}&quot;">​</a></h3><p>告警状态练习：条件持续3分钟，for=2m、group_wait=30s，是否恰好2分30秒收到通知？参考解答：不保证，首次评估与条件开始时刻不一致，投递排队和失败重试也有延迟。能够确定的是先满足规则持续期再经过通知层时序，实际到达需要接收端证据。不能拿静态YAML解析结果替代该证据。</p><h3 id="part-3-answer" tabindex="-1">缺失信号练习 <a class="header-anchor" href="#part-3-answer" aria-label="Permalink to &quot;缺失信号练习 {#part-3-answer}&quot;">​</a></h3><p>告警缺失练习：一个目标被删，up从0变成不存在，是故障恢复吗？参考解答：不是充分证据。up==0空向量只说明没有符合条件的当前序列，应以期望目标清单、absent_over_time和变更记录区分合法下线与监控盲区。目标合法退役后再更新期望清单与规则，避免永久Missing噪声。</p><h3 id="part-3-checklist" tabindex="-1">行动与后续边界 <a class="header-anchor" href="#part-3-checklist" aria-label="Permalink to &quot;行动与后续边界 {#part-3-checklist}&quot;">​</a></h3><p>告警复核清单应逐项回答：触发代表何种用户影响、谁接收、空数据怎么处理、如何稳定身份、抑制会否跨服务、怎样确认恢复。此课程交付固定状态语义、完整配置和失败推演；没有进行promtool执行、通知发送、HA故障切换或实际值班演练。读者应在组织环境补实测，不能仅以“YAML可解析”批准生产。</p><h3 id="part-3-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-3-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-3-selfcheck}&quot;">​</a></h3><p>练习：通过无限silence关闭噪声算规则修复吗？</p><details><summary>参考解答</summary><p>不算。需要有范围和时限的维护静默，并修复信号口径、聚合或行动条件，保留根因告警。</p></details><h3 id="part-3-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-3-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-3-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p>',51)])])}const f=a(n,[["render",l]]);export{g as __pageData,f as default};
